-- SB-66: invites carry the invitee's birth year, so the web app can check a
-- kid invite is for someone 13 or older, and accepting copies it to the new
-- member row. Generated by drizzle-kit; hand edits: this header and the
-- accept_household_invite replacement below (same as 0005 apart from
-- birth_year; CREATE OR REPLACE keeps its grants).

ALTER TABLE "household_invites" ADD COLUMN "birth_year" smallint;--> statement-breakpoint
ALTER TABLE "household_invites" ADD CONSTRAINT "household_invites_birth_year_check" CHECK ("household_invites"."birth_year" is null or "household_invites"."birth_year" between 1900 and 2200);
--> statement-breakpoint
CREATE OR REPLACE FUNCTION app.accept_household_invite(token text) RETURNS uuid
	LANGUAGE plpgsql VOLATILE SECURITY DEFINER
	SET search_path = pg_catalog, public
	AS $$
	DECLARE
		uid uuid := app.current_user_id();
		inv public.household_invites%ROWTYPE;
		u_email text;
		u_name text;
		u_verified boolean;
		new_member uuid;
	BEGIN
		IF uid IS NULL THEN
			RAISE EXCEPTION 'not signed in' USING ERRCODE = '42501';
		END IF;

		SELECT * INTO inv FROM public.household_invites i
		WHERE i.token_hash = encode(sha256(convert_to(token, 'UTF8')), 'hex')
		FOR UPDATE;
		IF NOT FOUND THEN
			RAISE EXCEPTION 'invite not found' USING ERRCODE = 'P0002';
		END IF;
		IF inv.accepted_at IS NOT NULL THEN
			RAISE EXCEPTION 'invite already accepted' USING ERRCODE = '22023';
		END IF;
		IF inv.expires_at <= now() THEN
			RAISE EXCEPTION 'invite expired' USING ERRCODE = '22023';
		END IF;

		SELECT u.email, u.name, u."emailVerified" INTO u_email, u_name, u_verified
		FROM neon_auth."user" u WHERE u.id = uid;
		IF NOT FOUND OR NOT u_verified OR lower(u_email) <> lower(inv.email) THEN
			RAISE EXCEPTION 'invite is for a different email' USING ERRCODE = '42501';
		END IF;

		IF EXISTS (
			SELECT 1 FROM public.household_members m
			WHERE m.household_id = inv.household_id AND m.user_id = uid
		) THEN
			RAISE EXCEPTION 'already a member of this household' USING ERRCODE = '23505';
		END IF;

		INSERT INTO public.household_members (household_id, user_id, role, display_name, birth_year)
		VALUES (
			inv.household_id,
			uid,
			inv.role,
			coalesce(
				inv.display_name,
				left(nullif(btrim(u_name), ''), 50),
				left(split_part(u_email, '@', 1), 50)
			),
			inv.birth_year
		)
		RETURNING id INTO new_member;

		UPDATE public.household_invites
		SET accepted_at = now(), accepted_member_id = new_member
		WHERE id = inv.id;

		RETURN new_member;
	END
	$$;
